     <GAP> prefix "Primary" w a1:Id params:ParamList? w suffix
     { if (params == null) params = new LinkedList<Id>();
       yyValue = ExprFactory.makeTemplateGapPrimary(createSpan(yyStart,yyCount), a1, params);
     };

